Tool response:
Tool: find_appointment_by_patient_and_time
Description: Find appointment ID by patient name and scheduled time
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_name": {
          "type": "string",
          "description": "Full name of the patient",
          "title": "Patient Name"
        },
        "scheduled_at": {
          "type": "string",
          "description": "Scheduled datetime of the appointment (ISO 8601 format)",
          "title": "Scheduled At"
        }
      },
      "required": [
        "patient_name",
        "scheduled_at"
      ]
    }

